import json, re, sys

R = "[redacted]"

def f(*p):
    return "".join(p)

# Sensitive values and phrases, most specific first.
VAL = [
    (f('$4,8', '00'), R),
    (f('4,8', '00'), R),
    (f('$1,9', '50'), R),
    (f('1,9', '50'), R),
    (f('$2,8', '50'), R),
    (f('2,8', '50'), R),
    (f('$5,8', '50'), R),
    (f('5,8', '50'), R),
    (f('$3', '50'), R),
    (f('$1', '50'), R),
    (f('3.', '08'), R),
    (f('3.1 ', 'months'), R + ' '),
    (f('3 fu', 'll months'), R),
    (f('2', '–3 days'), R),
    (f('into mo', 'nth 4'), R),
    (f('mo', 'nth 4'), R),
    (f('take-', 'home [redacted]'), R),
]

# Labels naming the sensitive categories.
WORDS = [f('inc', 'ome'), f('de', 'bt'), f('repay', 'ment'), f('take-', 'home')]

def esc(s):
    return json.dumps(s)[1:-1]

def redact(text):
    n = 0
    for old, new in VAL:
        if old in text:
            n += text.count(old)
            text = text.replace(old, new)
        eo, en = esc(old), esc(new)
        if eo != old and eo in text:
            n += text.count(eo)
            text = text.replace(eo, en)
    for w in WORDS:
        text, k = re.subn(re.escape(w), R, text, flags=re.IGNORECASE)
        n += k
    return text, n

def residual(text):
    r = 0
    for old, _ in VAL:
        r += text.count(old)
        if esc(old) != old:
            r += text.count(esc(old))
    for w in WORDS:
        r += len(re.findall(re.escape(w), text, flags=re.IGNORECASE))
    return r

def check(path, text):
    if path.endswith('.jsonl'):
        for i, line in enumerate(text.split('\n'), 1):
            if line.strip():
                try:
                    json.loads(line)
                except Exception as e:
                    return f"BROKEN line {i}: {type(e).__name__}"
        return "ok"
    if path.endswith('.json'):
        try:
            json.loads(text)
        except Exception as e:
            return f"BROKEN: {type(e).__name__}"
        return "ok"
    return "n/a (plain text)"

for path in sys.argv[1:]:
    with open(path, 'r+', encoding='utf-8', newline='') as fh:
        text = fh.read()
        new, n = redact(text)
        if n:
            fh.seek(0)
            fh.write(new)
            fh.truncate()
    print(f"{path}: replaced={n} residual={residual(new)} structure={check(path, new)}")

